/** Runtime helpers for TypeScript generated by scripts/php-tpl.py — PHP semantics for the few operations templates use. */
import { numberFormat as nf } from './format.js';
import { e as esc, jsonEncode as je } from './html.js';

export interface TplHelpers {
  u: (p: string) => string; money: (v: unknown) => string; fdate: (v: unknown, fmt?: string) => string; fdatetime: (v: unknown, fmt?: string) => string;
  csrfField: () => string; csrfToken: () => string; can: (k: string) => boolean;
  isDeliveryManager?: () => boolean; fixedStoreId?: () => number | null; activeStoreId?: () => number | null;
  getSetting: (k: string, d?: any) => any; phpDate?: (fmt: string, ts?: number) => string; strtotime?: (s: string) => number; time?: () => number;
  [k: string]: any;
}

export const e = (v: unknown): string => esc(v);
export const jsonEncode = (v: unknown): string => je(v);
export const T = (v: any): boolean => {
  if (v === null || v === undefined || v === false || v === 0 || v === '' || v === '0') return false;
  if (typeof v === 'number' && Number.isNaN(v)) return true;
  if (Array.isArray(v)) return v.length > 0;
  if (v instanceof Map) return v.size > 0;
  return true;
};
export const S = (v: any): string => {
  if (v === null || v === undefined || v === false) return '';
  if (v === true) return '1';
  return String(v);
};
export const phpEmpty = (v: any) => !T(v);
export const num = (v: any): number => {
  if (v === null || v === undefined || v === '' || v === false) return 0;
  if (v === true) return 1;
  const n = typeof v === 'number' ? v : parseFloat(String(v));
  return Number.isNaN(n) ? 0 : n;
};
export const int = (v: any): number => Math.trunc(num(v));
export const flt = (v: any): number => num(v);
export const add = (a: any, b: any): number => num(a) + num(b);
export const mod = (a: any, b: any): number => int(a) % int(b);
const isNumStr = (s: any) => typeof s === 'string' && /^\s*[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?\s*$/.test(s);
export function looseEq(a: any, b: any): boolean {
  if (a === null || a === undefined) a = null;
  if (b === null || b === undefined) b = null;
  if (a === null && b === null) return true;
  if (typeof a === 'boolean' || typeof b === 'boolean' || a === null || b === null) {
    if (a === null && typeof b === 'string') return b === '';
    if (b === null && typeof a === 'string') return a === '';
    return T(a) === T(b);
  }
  if (typeof a === 'string' && typeof b === 'string') return isNumStr(a) && isNumStr(b) ? parseFloat(a) === parseFloat(b) : a === b;
  if (typeof a === 'number' && typeof b === 'string') return isNumStr(b) ? a === parseFloat(b) : String(a) === b;
  if (typeof b === 'number' && typeof a === 'string') return isNumStr(a) ? b === parseFloat(a) : String(b) === a;
  return a === b;
}
export function cmp(a: any, b: any, op: string): boolean {
  let x = a, y = b;
  if (!(typeof a === 'string' && typeof b === 'string' && !(isNumStr(a) && isNumStr(b)))) { x = num(a); y = num(b); }
  switch (op) { case '<': return x < y; case '<=': return x <= y; case '>': return x > y; default: return x >= y; }
}
export const elvis = (a: any, b: () => any) => (T(a) ? a : b());
export const count = (v: any): number => (Array.isArray(v) ? v.length : v instanceof Map ? v.size : v && typeof v === 'object' ? Object.keys(v).length : 0);
export function entries(v: any): [any, any][] {
  if (v instanceof Map) return [...v.entries()];
  if (Array.isArray(v)) return v.map((x, i) => [i, x]);
  return v && typeof v === 'object' ? Object.entries(v) : [];
}
export const values = (v: any): any[] => (v instanceof Map ? [...v.values()] : Array.isArray(v) ? v : v && typeof v === 'object' ? Object.values(v) : []);
export const copy = (v: any) => (Array.isArray(v) ? [...v] : v instanceof Map ? new Map(v) : v && typeof v === 'object' ? { ...v } : v);
export const toArray = (v: any) => (Array.isArray(v) ? v : v === null || v === undefined ? [] : [v]);
export const inArray = (needle: any, hay: any[], strict = false) => (strict ? hay.includes(needle) : hay.some((x) => looseEq(x, needle)));
export const implode = (g: string, arr: any[]) => values(arr).map(S).join(g);
export const numberFormat = (n: any, dec = 2) => nf(num(n), int(dec));
export const ucfirst = (s: any) => { const t = S(s); return t.charAt(0).toUpperCase() + t.slice(1); };
export const strtoupper = (s: any) => S(s).toUpperCase();
export const strtolower = (s: any) => S(s).toLowerCase();
export const strPad = (s: any, len: number, pad = ' ', type = 1) => (type === 0 ? S(s).padStart(len, pad) : S(s).padEnd(len, pad)); // STR_PAD_RIGHT=1 default; STR_PAD_LEFT=0
export const strlen = (s: any) => Buffer.byteLength(S(s));
export const trim = (s: any) => S(s).replace(/^[ \t\n\r\0\x0B]+|[ \t\n\r\0\x0B]+$/g, '');
export const ltrim = (s: any) => S(s).replace(/^[ \t\n\r\0\x0B]+/, '');
export const rtrim = (s: any) => S(s).replace(/[ \t\n\r\0\x0B]+$/, '');
export const round = (n: any, d = 0) => { const m = 10 ** d; const x = num(n) * m; return Math.sign(x) * Math.round(Math.abs(x) + 1e-9) / m; };
export const floor = (n: any) => Math.floor(num(n));
export const ceil = (n: any) => Math.ceil(num(n));
export const abs = (n: any) => Math.abs(num(n));
export const max = (...a: any[]) => Math.max(...(a.length === 1 ? values(a[0]) : a).map(num));
export const min = (...a: any[]) => Math.min(...(a.length === 1 ? values(a[0]) : a).map(num));
export const nl2br = (s: any) => S(s).replace(/(\r\n|\n\r|\n|\r)/g, '<br />$1');
export const isNumeric = (v: any) => typeof v === 'number' || isNumStr(v);
export const urlencode = (s: any) => encodeURIComponent(S(s)).replace(/[!'()*~]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`).replace(/%20/g, '+');
export const rawurlencode = (s: any) => encodeURIComponent(S(s)).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
export const httpBuildQuery = (o: Record<string, any>) => Object.entries(o).filter(([, v]) => v !== null && v !== undefined).map(([k, v]) => `${urlencode(k)}=${urlencode(v)}`).join('&');
export const arrayKeys = (o: any) => entries(o).map(([k]) => k);
export const arrayValues = (o: any) => values(o);
export const arraySum = (a: any) => values(a).reduce((x: number, y: any) => x + num(y), 0);
export const arrayColumn = (rows: any[], col: string) => values(rows).map((r: any) => r?.[col]);
export const arraySlice = (a: any, off: number, len?: number) => values(a).slice(off, len === undefined ? undefined : off + len);
export const strRepeat = (s: any, n: number) => S(s).repeat(Math.max(0, n));
export const substr = (s: any, off: number, len?: number) => { const t = S(s); const o = off < 0 ? Math.max(0, t.length + off) : off; return len === undefined ? t.slice(o) : t.slice(o, o + len); };
export const strReplace = (a: any, b: any, s: any) => S(s).split(S(a)).join(S(b));
export const isArray = (v: any) => Array.isArray(v) || v instanceof Map;
export const isNull = (v: any) => v === null || v === undefined;
export const isString = (v: any) => typeof v === 'string';
export const arrayKeyExists = (k: any, o: any) => (o instanceof Map ? o.has(k) : !!o && Object.prototype.hasOwnProperty.call(o, k));
export const arrayMerge = (...a: any[]) => Object.assign({}, ...a);
export const strpos = (h: any, n: any) => { const i = S(h).indexOf(S(n)); return i < 0 ? false : i; };
export const strContains = (h: any, n: any) => S(h).includes(S(n));
export const strStartsWith = (h: any, n: any) => S(h).startsWith(S(n));
export const ucwords = (s: any) => S(s).replace(/(^|[ \t\r\n\f\v])([a-z])/g, (_m, a, b) => a + b.toUpperCase());
export const sprintf = (fmt: string, ...a: any[]) => { let i = 0; return fmt.replace(/%(?:(\d+)\$)?([-0 ]?)(\d*)(?:\.(\d+))?([sdfF%])/g, (_m, _pos, flag, w, p, t) => { if (t === '%') return '%'; const v = a[i++]; let r = t === 's' ? S(v) : t === 'd' ? String(int(v)) : num(v).toFixed(p ? Number(p) : 6); if (w) r = flag === '-' ? r.padEnd(Number(w), ' ') : r.padStart(Number(w), flag === '0' ? '0' : ' '); return r; }); };
export const jsonDecode = (s: any) => { try { return JSON.parse(S(s)); } catch { return null; } };
export const arrayFilter = (a: any, fn?: (x: any) => boolean) => (Array.isArray(a) ? a.filter(fn ?? T) : a);
export const arrayMap = (fn: (x: any) => any, a: any) => values(a).map(fn);
export const arrayFlip = (a: any) => new Map(entries(a).map(([k, v]) => [v, k]));
export const arraySearch = (n: any, a: any) => { const f = entries(a).find(([, v]) => v === n); return f ? f[0] : false; };
export const wordwrap = (s: any) => S(s);
